import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class Solution {
    private Solution() {}

    public static final class Walkthrough {
        private final List<String> cards;
        private final boolean closed;

        private Walkthrough(List<String> cards, boolean closed) {
            this.cards = Collections.unmodifiableList(new ArrayList<String>(cards));
            this.closed = closed;
        }

        public List<String> getCards() {
            return cards;
        }

        public boolean isClosed() {
            return closed;
        }
    }

    public static Walkthrough openWalkthrough(List<String> cards) {
        validateCards(cards);
        return new Walkthrough(cards, false);
    }

    public static Walkthrough closeWalkthrough(Walkthrough walkthrough) {
        if (walkthrough == null) {
            throw new IllegalArgumentException("walkthrough is null");
        }
        return new Walkthrough(walkthrough.getCards(), true);
    }

    public static boolean allVisible(List<Boolean> visibility) {
        if (visibility == null) {
            throw new IllegalArgumentException("visibility is null");
        }
        boolean result = true;
        for (Boolean visible : visibility) {
            if (visible == null) {
                throw new IllegalArgumentException("null visibility");
            }
            if (!visible.booleanValue()) {
                result = false;
            }
        }
        return result;
    }

    private static void validateCards(List<String> cards) {
        if (cards == null) {
            throw new IllegalArgumentException("cards is null");
        }
        for (String card : cards) {
            if (card == null || card.isEmpty()) {
                throw new IllegalArgumentException("invalid card");
            }
        }
    }
}

