import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        testOpenStateAndCardSnapshot();
        testCloseTransitions();
        testCardValidation();
        testVisibility();
    }

    private static void testOpenStateAndCardSnapshot() {
        ArrayList<String> cards = new ArrayList<String>(Arrays.asList("first", " second ", "third"));
        Solution.Walkthrough walkthrough = Solution.openWalkthrough(cards);
        check(!walkthrough.isClosed(), "new walkthrough is open");
        equals(Arrays.asList("first", " second ", "third"), walkthrough.getCards(),
                "card text and order preserved");

        cards.set(0, "changed");
        cards.clear();
        equals(Arrays.asList("first", " second ", "third"), walkthrough.getCards(),
                "walkthrough snapshots caller list");

        boolean unmodifiable = false;
        try {
            walkthrough.getCards().add("new");
        } catch (UnsupportedOperationException expected) {
            unmodifiable = true;
        }
        check(unmodifiable, "getCards returns unmodifiable list");

        Solution.Walkthrough empty = Solution.openWalkthrough(Collections.<String>emptyList());
        check(empty.getCards().isEmpty(), "empty card list valid");
        check(!empty.isClosed(), "empty walkthrough still starts open");
    }

    private static void testCloseTransitions() {
        ArrayList<String> source = new ArrayList<String>(Arrays.asList("a", "b"));
        Solution.Walkthrough open = Solution.openWalkthrough(source);
        Solution.Walkthrough closed = Solution.closeWalkthrough(open);
        check(closed != open, "closing returns a new state");
        check(!open.isClosed(), "original state not modified");
        check(closed.isClosed(), "new state is closed");
        equals(open.getCards(), closed.getCards(), "cards preserved while closing");

        source.clear();
        equals(Arrays.asList("a", "b"), closed.getCards(), "closed state has isolated cards");

        Solution.Walkthrough closedAgain = Solution.closeWalkthrough(closed);
        check(closedAgain != closed, "already closed input still yields a new state");
        check(closedAgain.isClosed(), "reclosed state remains closed");
        equals(Arrays.asList("a", "b"), closedAgain.getCards(), "reclosed cards preserved");

        expectIllegalArgument(new Action() {
            public void run() { Solution.closeWalkthrough(null); }
        }, "null walkthrough");
    }

    private static void testCardValidation() {
        expectIllegalArgument(new Action() {
            public void run() { Solution.openWalkthrough(null); }
        }, "null card list");
        expectIllegalArgument(new Action() {
            public void run() { Solution.openWalkthrough(Arrays.asList("valid", null)); }
        }, "null card");
        expectIllegalArgument(new Action() {
            public void run() { Solution.openWalkthrough(Arrays.asList("valid", "")); }
        }, "empty card");

        Solution.Walkthrough blank = Solution.openWalkthrough(Collections.singletonList(" "));
        equals(" ", blank.getCards().get(0), "nonempty blank card is not normalized or rejected");
    }

    private static void testVisibility() {
        check(Solution.allVisible(Collections.<Boolean>emptyList()), "empty visibility list is vacuously true");
        check(Solution.allVisible(Arrays.asList(Boolean.TRUE, Boolean.TRUE, Boolean.TRUE)),
                "all true entries visible");
        check(!Solution.allVisible(Arrays.asList(Boolean.TRUE, Boolean.FALSE, Boolean.TRUE)),
                "one false entry makes result false");

        expectIllegalArgument(new Action() {
            public void run() { Solution.allVisible(null); }
        }, "null visibility list");
        final List<Boolean> malformed = new ArrayList<Boolean>(Arrays.asList(Boolean.FALSE, null));
        expectIllegalArgument(new Action() {
            public void run() { Solution.allVisible(malformed); }
        }, "null entry must be validated even when an earlier entry is false");
        equals(Arrays.asList(Boolean.FALSE, null), malformed, "visibility list not mutated");
    }

    private interface Action { void run(); }

    private static void expectIllegalArgument(Action action, String label) {
        try {
            action.run();
            throw new AssertionError("Expected IllegalArgumentException: " + label);
        } catch (IllegalArgumentException expected) {
            // expected
        }
    }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void equals(Object expected, Object actual, String message) {
        if (expected == null ? actual != null : !expected.equals(actual)) {
            throw new AssertionError(message + ": expected=" + expected + ", actual=" + actual);
        }
    }
}

