import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        testNormalTraceAndNoSwapTermination();
        testAlreadySortedAndTinyArrays();
        testNumericBoundariesAndDuplicates();
        testAllDefensiveCopiesAndUnmodifiableList();
        testNullRejection();
    }

    private static void testNormalTraceAndNoSwapTermination() {
        int[] input = {1, 3, 2};
        Solution.SortTrace trace = Solution.traceDescending(input);
        assertArrayEquals(new int[] {1, 3, 2}, input, "input not mutated");
        assertArrayEquals(new int[] {3, 2, 1}, trace.getSorted(), "descending result");

        List<int[]> passes = trace.getPasses();
        equals(2, passes.size(), "swap pass plus final no-swap pass recorded");
        assertArrayEquals(new int[] {3, 2, 1}, passes.get(0), "first completed pass");
        assertArrayEquals(new int[] {3, 2, 1}, passes.get(1), "final no-swap pass");

        Solution.SortTrace two = Solution.traceDescending(new int[] {1, 2});
        equals(2, two.getPasses().size(), "two elements record swap pass and subsequent no-swap pass");
        assertArrayEquals(new int[] {2, 1}, two.getPasses().get(0), "two-element swap pass");
        assertArrayEquals(new int[] {2, 1}, two.getPasses().get(1), "two-element no-swap pass");
    }

    private static void testAlreadySortedAndTinyArrays() {
        Solution.SortTrace sorted = Solution.traceDescending(new int[] {5, 4, 3});
        equals(1, sorted.getPasses().size(), "already sorted nontrivial array has final no-swap pass");
        assertArrayEquals(new int[] {5, 4, 3}, sorted.getPasses().get(0), "no-swap snapshot");

        Solution.SortTrace empty = Solution.traceDescending(new int[0]);
        assertArrayEquals(new int[0], empty.getSorted(), "empty sorted result");
        check(empty.getPasses().isEmpty(), "empty input has no passes");

        Solution.SortTrace singleton = Solution.traceDescending(new int[] {7});
        assertArrayEquals(new int[] {7}, singleton.getSorted(), "singleton sorted result");
        check(singleton.getPasses().isEmpty(), "singleton has no passes");
    }

    private static void testNumericBoundariesAndDuplicates() {
        int[] input = {Integer.MIN_VALUE, 0, Integer.MAX_VALUE, -1, Integer.MAX_VALUE};
        Solution.SortTrace trace = Solution.traceDescending(input);
        assertArrayEquals(new int[] {Integer.MAX_VALUE, Integer.MAX_VALUE, 0, -1, Integer.MIN_VALUE},
                trace.getSorted(), "numeric comparison handles integer limits without overflow");

        Solution.SortTrace duplicates = Solution.traceDescending(new int[] {2, 2});
        equals(1, duplicates.getPasses().size(), "equal values require only no-swap pass");
        assertArrayEquals(new int[] {2, 2}, duplicates.getSorted(), "duplicates preserved");
    }

    private static void testAllDefensiveCopiesAndUnmodifiableList() {
        Solution.SortTrace trace = Solution.traceDescending(new int[] {1, 3, 2});
        int[] sorted1 = trace.getSorted();
        sorted1[0] = -999;
        assertArrayEquals(new int[] {3, 2, 1}, trace.getSorted(), "getSorted returns defensive copies");
        check(sorted1 != trace.getSorted(), "getSorted allocates a new array each call");

        List<int[]> passes1 = trace.getPasses();
        passes1.get(0)[0] = -777;
        List<int[]> passes2 = trace.getPasses();
        assertArrayEquals(new int[] {3, 2, 1}, passes2.get(0), "pass arrays returned defensively");
        check(passes1.get(0) != passes2.get(0), "pass arrays are newly copied across calls");

        boolean unmodifiable = false;
        try {
            passes1.add(new int[0]);
        } catch (UnsupportedOperationException expected) {
            unmodifiable = true;
        }
        check(unmodifiable, "returned pass list unmodifiable");
    }

    private static void testNullRejection() {
        try {
            Solution.traceDescending(null);
            throw new AssertionError("Expected IllegalArgumentException for null input");
        } catch (IllegalArgumentException expected) {
            // expected
        }
    }

    private static void assertArrayEquals(int[] expected, int[] actual, String message) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(message + ": expected=" + Arrays.toString(expected)
                    + ", actual=" + Arrays.toString(actual));
        }
    }

    private static void equals(int expected, int actual, String message) {
        if (expected != actual) throw new AssertionError(message + ": expected=" + expected + ", actual=" + actual);
    }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }
}

