def parse_sections(lines):
    try:
        pending = list(lines)
    except TypeError as exc:
        raise TypeError("lines must be iterable") from exc
    if any(not isinstance(line, str) for line in pending):
        raise TypeError("every line must be a string")

    result = []
    names = set()
    current = None

    for original in pending:
        stripped = original.strip()
        if not stripped or stripped.startswith("#"):
            continue

        if "=" in stripped:
            if current is None:
                raise ValueError("assignment appears before a section")
            key, value = stripped.split("=", 1)
            key = key.strip()
            value = value.strip()
            if not key:
                raise ValueError("assignment key is empty")
            current["values"][key] = value
            continue

        if stripped.startswith("[") or stripped.endswith("]"):
            if not (stripped.startswith("[") and stripped.endswith("]")):
                raise ValueError("malformed section header")
            name = stripped[1:-1]
            if not name or name != name.strip() or "[" in name or "]" in name:
                raise ValueError("malformed section header")
            if name in names:
                raise ValueError("duplicate section")
            current = {"name": name, "values": {}}
            result.append(current)
            names.add(name)
            continue

        if current is None:
            raise ValueError("assignment appears before a section")
        raise ValueError("assignment is missing equals sign")

    return result

