import unittest
from solution import parse_sections


class ParseSectionsTests(unittest.TestCase):
    def test_normal_comments_blanks_replacement_and_order(self):
        lines = [
            "  # comment", "", "[first]", " a = 1 ", "b=two", "a=changed",
            "[second]", "value = [brackets]", "empty=", "tail=ends]",
        ]
        result = parse_sections(lines)
        self.assertEqual(result, [
            {"name": "first", "values": {"a": "changed", "b": "two"}},
            {"name": "second", "values": {
                "value": "[brackets]", "empty": "", "tail": "ends]"
            }},
        ])
        self.assertEqual(list(result[0]["values"].keys()), ["a", "b"])

    def test_generator_and_fresh_results(self):
        source = (line for line in ["[one]", "x=1"])
        first = parse_sections(source)
        self.assertEqual(first, [{"name": "one", "values": {"x": "1"}}])
        second = parse_sections(["[one]", "x=1"])
        self.assertIsNot(first, second)
        self.assertIsNot(first[0], second[0])
        self.assertIsNot(first[0]["values"], second[0]["values"])
        first[0]["values"]["x"] = "changed"
        self.assertEqual(second[0]["values"]["x"], "1")

    def test_empty_and_comment_only(self):
        self.assertEqual(parse_sections([]), [])
        self.assertEqual(parse_sections([" ", "\t# ignored", "#also ignored"]), [])

    def test_header_name_rules(self):
        self.assertEqual(parse_sections(["[a b]", "x=y"]), [{"name": "a b", "values": {"x": "y"}}])
        bad = ("[]", "[ name]", "[name ]", "[[name]", "[name]]", "[name", "name]")
        for line in bad:
            with self.subTest(line=line):
                with self.assertRaises(ValueError):
                    parse_sections([line])

    def test_assignment_before_header_empty_key_and_invalid_lines(self):
        cases = [
            ["x=1"],
            ["[s]", " = value"],
            ["[s]", "plain text"],
            ["[s]", "name[broken"],
            ["[s]", "broken]"],
        ]
        for lines in cases:
            with self.subTest(lines=lines):
                with self.assertRaises(ValueError):
                    parse_sections(lines)

    def test_duplicate_sections(self):
        with self.assertRaises(ValueError):
            parse_sections(["[same]", "x=1", "[same]", "y=2"])

    def test_type_errors(self):
        for value in (None, 42, True):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    parse_sections(value)
        for lines in (["[s]", 1], [b"[s]"]):
            with self.subTest(lines=lines):
                with self.assertRaises(TypeError):
                    parse_sections(lines)

    def test_split_only_at_first_equals(self):
        self.assertEqual(parse_sections(["[s]", "key = a=b=c"]), [
            {"name": "s", "values": {"key": "a=b=c"}}
        ])


if __name__ == "__main__":
    unittest.main()

