#[derive(Clone, Debug, PartialEq, Eq)]
pub enum FieldError {
    EmptyName,
    Malformed,
    Duplicate,
}

pub fn read_tagged_field(input: &str, name: &str) -> Result<Option<String>, FieldError> {
    if name.is_empty() {
        return Err(FieldError::EmptyName);
    }

    let bytes = input.as_bytes();
    let mut pos = 0usize;
    let mut result = None;
    let mut duplicate = false;

    while pos < bytes.len() {
        if bytes[pos] != b'[' {
            pos += 1;
            continue;
        }

        let next = bytes.get(pos + 1).copied();
        if next == Some(b'/') {
            return Err(FieldError::Malformed);
        }
        if !next.map_or(false, |byte| byte.is_ascii_alphabetic()) {
            pos += 1;
            continue;
        }

        let open_end = input[pos + 1..]
            .find(']')
            .map(|offset| pos + 1 + offset)
            .ok_or(FieldError::Malformed)?;
        let open_name = &input[pos + 1..open_end];
        let close = format!("[/{open_name}]");
        let content_start = open_end + 1;
        let relative_end = input[content_start..]
            .find(&close)
            .ok_or(FieldError::Malformed)?;
        let content_end = content_start + relative_end;
        let content = &input[content_start..content_end];

        if content.as_bytes().windows(2).any(|window| {
            window[0] == b'['
                && (window[1] == b'/' || window[1].is_ascii_alphabetic())
        }) {
            return Err(FieldError::Malformed);
        }

        if open_name == name {
            if result.is_some() {
                duplicate = true;
            } else {
                result = Some(content.to_owned());
            }
        }
        pos = content_end + close.len();
    }

    if duplicate {
        Err(FieldError::Duplicate)
    } else {
        Ok(result)
    }
}

