mod solution;

use solution::{read_tagged_field, FieldError};

#[test]
fn reads_exact_content_and_supports_extended_names() {
    assert_eq!(read_tagged_field("before[item-name]  hello\n [/item-name]after", "item-name").unwrap(), Some("  hello\n ".to_string()));
    assert_eq!(read_tagged_field("[a/b]value[/a/b]", "a/b").unwrap(), Some("value".to_string()));
    assert_eq!(read_tagged_field("[empty][/empty]", "empty").unwrap(), Some(String::new()));
}

#[test]
fn permits_consecutive_fields_and_ordinary_brackets() {
    let input = "[a]one[/a] text [1] [ [b]two[/b] tail";
    assert_eq!(read_tagged_field(input, "a").unwrap(), Some("one".to_string()));
    assert_eq!(read_tagged_field(input, "b").unwrap(), Some("two".to_string()));
    assert_eq!(read_tagged_field(input, "missing").unwrap(), None);
}

#[test]
fn rejects_empty_requested_name_without_mutating_input() {
    let input = String::from("[a]x[/a]");
    let before = input.clone();
    assert_eq!(read_tagged_field(&input, ""), Err(FieldError::EmptyName));
    assert_eq!(input, before);
}

#[test]
fn detects_unmatched_mismatched_and_nested_delimiters() {
    for input in [
        "[a]text",
        "text[/a]",
        "[a]text[/b]",
        "[a][b]x[/b][/a]",
        "[a]x[/a][/b]",
        "[a",
        "[/a",
        "[/]",
    ] {
        assert_eq!(read_tagged_field(input, "a"), Err(FieldError::Malformed), "{input}");
    }
}

#[test]
fn validates_whole_document_and_malformed_beats_duplicate() {
    let duplicate = "[x]one[/x] middle [x]two[/x]";
    assert_eq!(read_tagged_field(duplicate, "x"), Err(FieldError::Duplicate));

    let duplicate_then_bad = "[x]one[/x][x]two[/x][y]broken[/z]";
    assert_eq!(read_tagged_field(duplicate_then_bad, "x"), Err(FieldError::Malformed));

    let early_match_then_bad = "[x]ok[/x] trailing [/orphan]";
    assert_eq!(read_tagged_field(early_match_then_bad, "x"), Err(FieldError::Malformed));
}

#[test]
fn delimiters_and_names_are_case_sensitive() {
    assert_eq!(read_tagged_field("[Name]x[/Name]", "name").unwrap(), None);
    assert_eq!(read_tagged_field("[Name]x[/name]", "Name"), Err(FieldError::Malformed));
}

