mod solution;

use solution::{Decision, Policy, RequestKind, Rule};

fn rule(suffix: &str, kind: Option<RequestKind>, decision: Decision) -> Rule {
    Rule { host_suffix: suffix.to_string(), kind, decision }
}

#[test]
fn exact_and_subdomain_suffixes_match_but_partial_suffixes_do_not() {
    let policy = match Policy::new(vec![rule("example.com", None, Decision::Reject)]) {
        Ok(value) => value,
        Err(_) => panic!("valid policy rejected"),
    };
    assert!(policy.evaluate("example.com", RequestKind::Code) == Decision::Reject);
    assert!(policy.evaluate("a.b.example.com", RequestKind::Media) == Decision::Reject);
    assert!(policy.evaluate("notexample.com", RequestKind::Style) == Decision::Permit);
    assert!(policy.evaluate("example.com.evil", RequestKind::Code) == Decision::Permit);
}

#[test]
fn kind_filter_and_insertion_order_are_respected() {
    let policy = Policy::new(vec![
        rule("assets.test", Some(RequestKind::Media), Decision::Permit),
        rule("assets.test", None, Decision::Reject),
        rule("assets.test", Some(RequestKind::Media), Decision::Reject),
    ]).unwrap();
    assert!(policy.evaluate("assets.test", RequestKind::Media) == Decision::Permit);
    assert!(policy.evaluate("assets.test", RequestKind::Code) == Decision::Reject);
    assert!(policy.evaluate("assets.test", RequestKind::Style) == Decision::Reject);
}

