fn empty_policy_and_invalid_evaluated_hosts_default_to_permit() {
    let empty = Policy::new(Vec::new()).unwrap();
    assert!(empty.evaluate("valid", RequestKind::Code) == Decision::Permit);

    let rejecting = Policy::new(vec![rule("valid", None, Decision::Reject)]).unwrap();
    for host in ["", "Upper", "has_space", "é", "valid/"] {
        assert!(rejecting.evaluate(host, RequestKind::Code) == Decision::Permit);
    }
}

