    let hyphen = Policy::new(vec![rule("-", None, Decision::Reject)]).unwrap();
    assert!(dot.evaluate(".", RequestKind::Code) == Decision::Reject);
    assert!(hyphen.evaluate("-", RequestKind::Style) == Decision::Reject);
}

